use xiom.io;
fn make_pizza(topping: Str) -> Str {
  return "Pizza with " + topping;
}

fn make_cheese_pizza() -> Str {
  return make_pizza("cheese");
}

fn main() {
  io.println(make_cheese_pizza());
  io.println(make_pizza("pepperoni"));
}
